create table if not exists public.apex_order_status_history (id bigint generated by default as identity primary key, order_id bigint not null references public.apex_orders(id) on delete cascade, status text not null, note text not null default '', changed_by uuid references auth.users(id), created_at timestamptz not null default now()); alter table public.apex_order_status_history enable row level security; create policy "customer reads own order status history" on public.apex_order_status_history for select to authenticated using (exists(select 1 from public.apex_orders o where o.id=order_id and o.user_id=auth.uid())); create policy "admins manage order status history" on public.apex_order_status_history for all to authenticated using (exists(select 1 from public.apex_admins a where a.user_id=auth.uid())) with check (exists(select 1 from public.apex_admins a where a.user_id=auth.uid()));